-- Merchant Service schema (database: merchant_db, owner: merchant_svc).
-- Written to run unchanged on PostgreSQL 16 (runtime) and H2 in PostgreSQL mode (unit/slice tests):
-- no jsonb, no char(n), no DB-side uuid generation (ids are generated by the application).

create table merchants (
    id                    uuid                     primary key,
    owner_user_id         varchar(64)              not null,
    business_name         varchar(150)             not null,
    business_reg_no       varchar(64),
    contact_email         varchar(254)             not null,
    contact_phone         varchar(32)              not null,
    address_line          varchar(255)             not null,
    city                  varchar(100)             not null,
    website               varchar(255),
    status                varchar(16)              not null,
    decided_by            varchar(64),
    decided_at            timestamp with time zone,
    decision_reason       varchar(500),
    rate_limit_per_minute integer                  not null default 60,
    created_at            timestamp with time zone not null,
    updated_at            timestamp with time zone not null,
    version               bigint                   not null default 0,
    constraint uq_merchants_owner unique (owner_user_id),
    constraint ck_merchants_status check (status in ('PENDING', 'APPROVED', 'REJECTED', 'SUSPENDED')),
    constraint ck_merchants_rate check (rate_limit_per_minute between 1 and 100000)
);
create index ix_merchants_status on merchants (status);

create table api_keys (
    id               uuid                     primary key,
    merchant_id      uuid                     not null references merchants (id),
    label            varchar(100)             not null,
    environment      varchar(8)               not null,
    key_prefix       varchar(24)              not null,
    key_hash         varchar(64)              not null,
    status           varchar(12)              not null,
    expires_at       timestamp with time zone,
    last_used_at     timestamp with time zone,
    rotated_from_id  uuid,
    created_at       timestamp with time zone not null,
    revoked_at       timestamp with time zone,
    constraint uq_api_keys_prefix unique (key_prefix),
    constraint ck_api_keys_env check (environment in ('LIVE', 'TEST')),
    constraint ck_api_keys_status check (status in ('ACTIVE', 'REVOKED'))
);
create index ix_api_keys_merchant on api_keys (merchant_id);

create table oauth_clients (
    id            uuid                     primary key,
    merchant_id   uuid                     not null references merchants (id),
    client_id     varchar(40)              not null,
    secret_hash   varchar(64)              not null,
    label         varchar(100)             not null,
    environment   varchar(8)               not null,
    scopes        varchar(200)             not null,
    status        varchar(12)              not null,
    last_used_at  timestamp with time zone,
    created_at    timestamp with time zone not null,
    revoked_at    timestamp with time zone,
    constraint uq_oauth_clients_client_id unique (client_id),
    constraint ck_oauth_clients_env check (environment in ('LIVE', 'TEST')),
    constraint ck_oauth_clients_status check (status in ('ACTIVE', 'REVOKED'))
);
create index ix_oauth_clients_merchant on oauth_clients (merchant_id);

create table webhook_configs (
    merchant_id        uuid                     primary key references merchants (id),
    url                varchar(500)             not null,
    secret_ciphertext  varchar(512)             not null,
    secret_hint        varchar(16)              not null,
    active             boolean                  not null default true,
    events             varchar(500)             not null default '*',
    last_test_at       timestamp with time zone,
    last_test_status   varchar(100),
    created_at         timestamp with time zone not null,
    updated_at         timestamp with time zone not null
);

create table merchant_orders (
    id                uuid                     primary key,
    merchant_id       uuid                     not null references merchants (id),
    external_ref      varchar(100),
    idempotency_key   varchar(100),
    request_hash      varchar(64),
    parcel_id         varchar(64),
    tracking_no       varchar(40),
    status            varchar(24)              not null,
    sandbox           boolean                  not null default false,
    source            varchar(12)              not null,
    recipient_name    varchar(120)             not null,
    recipient_phone   varchar(32)              not null,
    pickup_address    varchar(300)             not null,
    pickup_city       varchar(100)             not null,
    pickup_postal     varchar(16),
    dropoff_address   varchar(300)             not null,
    dropoff_city      varchar(100)             not null,
    dropoff_postal    varchar(16),
    weight_kg         numeric(8, 2)            not null,
    size              varchar(10)              not null,
    description       varchar(200),
    notes             varchar(500),
    fee_amount        numeric(12, 2),
    fee_currency      varchar(3),
    failure_reason    varchar(300),
    last_event_at     timestamp with time zone,
    created_at        timestamp with time zone not null,
    updated_at        timestamp with time zone not null,
    version           bigint                   not null default 0,
    constraint uq_orders_tracking unique (tracking_no),
    constraint uq_orders_idem unique (merchant_id, idempotency_key),
    constraint uq_orders_extref unique (merchant_id, external_ref),
    constraint ck_orders_status check (status in ('PENDING', 'CREATED', 'ASSIGNED', 'PICKED_UP', 'IN_TRANSIT',
        'OUT_FOR_DELIVERY', 'DELIVERED', 'FAILED', 'RESCHEDULED', 'RETURNED', 'CANCELLED')),
    constraint ck_orders_source check (source in ('API', 'PORTAL', 'BULK')),
    constraint ck_orders_size check (size in ('SMALL', 'MEDIUM', 'LARGE'))
);
create index ix_orders_merchant_created on merchant_orders (merchant_id, created_at);
create index ix_orders_merchant_status on merchant_orders (merchant_id, status);
create index ix_orders_parcel on merchant_orders (parcel_id);

create table order_status_history (
    id            uuid                     primary key,
    order_id      uuid                     not null references merchant_orders (id),
    event_id      varchar(64),
    from_status   varchar(24),
    to_status     varchar(24)              not null,
    occurred_at   timestamp with time zone not null,
    note          varchar(300),
    constraint uq_order_history_event unique (order_id, event_id)
);
create index ix_order_history_order on order_status_history (order_id, occurred_at);

-- Idempotent consumer: every parcel event handled by this service is recorded here.
create table processed_events (
    event_id      varchar(64)              primary key,
    event_type    varchar(100)             not null,
    processed_at  timestamp with time zone not null
);

-- Transactional outbox: merchant.* events are written in the same transaction as the data change
-- and published to RabbitMQ (swiftdrop.events) by the relay.
create table outbox_events (
    id            uuid                     primary key,
    event_id      varchar(64)              not null,
    event_type    varchar(100)             not null,
    aggregate_id  varchar(64)              not null,
    payload       varchar(4000)            not null,
    created_at    timestamp with time zone not null,
    published_at  timestamp with time zone,
    attempts      integer                  not null default 0,
    last_error    varchar(300),
    constraint uq_outbox_event_id unique (event_id)
);
create index ix_outbox_unpublished on outbox_events (published_at, created_at);
